// The Krunker map schema of kn_editor_mcp: prefabs, textures, object properties, map keys,
// triggers and limits. Data, not code: tools/editor-mcp/data/schema.json (generated by
// gen/gen_schema.py from the v3.1.1 editor tables and the v7.1.4 reference) is embedded at
// build time; --schema FILE or <root>/tools/editor-mcp/data/schema.json overrides it.
#pragma once
#include <cJSON.h>
#include <stddef.h>

typedef enum {
    PT_VEC3, PT_NUM, PT_INT, PT_BOOL_PRESENT, PT_BOOL_ABSENT, PT_STR, PT_COLOR, PT_TEXTURE, PT_FACES, PT_ANY,
} PropType;

typedef struct {
    int id;
    const char *name, *label, *category, *since;
    double default_size[3];
    double scale;
    int native;
    const cJSON *flags;   // array of flag names
    const cJSON *aliases; // array of older names
    const cJSON *json;    // the whole entry
} SchemaPrefab;

typedef struct {
    const char *prop, *key, *palette_key, *since, *desc;
    PropType type;
    const cJSON *def;     // NULL: no default
    const cJSON *alt_keys;
    int has_min, has_max;
    double min, max;
    int decimals;         // -1 none
    int max_length;       // -1 none
    const cJSON *when_flags, *when_prefabs, *when_not_flags;
    const cJSON *json;
} SchemaProp;

// Loads the schema: `path` if given, else <root>/tools/editor-mcp/data/schema.json when present,
// else the embedded copy. 0 on success; err gets a message otherwise.
int schema_load(const char *path, const char *root, char *err, size_t errsz);
const char *schema_source(void);
const cJSON *schema_json(void);

int schema_prefab_count(void);
const SchemaPrefab *schema_prefab(int id);          // NULL out of range
// "CUBE", "cube", "Spawn Point", an alias ("BOT"), or a number ("5"). -1 unknown.
int schema_prefab_find(const char *name);
// A prefab reference in JSON: number or string. -1 unknown.
int schema_prefab_from_json(const cJSON *v);
int schema_prefab_has_flag(int id, const char *flag);

int schema_prop_count(void);
const SchemaProp *schema_prop_at(int index);
const SchemaProp *schema_prop_by_key(const char *key);   // map key or one of its alt keys
const SchemaProp *schema_prop_lookup(const char *name);  // friendly name, else map key
int schema_prop_allowed(const SchemaProp *p, int prefab);
const char *schema_prop_type_name(PropType t);
// Keys every object may carry whatever its prefab (p, s, si, r, i, id, objUUID).
int schema_core_key(const char *key);

int schema_texture_count(void);
const char *schema_texture_name(int index);          // NULL out of range
int schema_texture_find(const char *name);           // case-insensitive name or number, -1
int schema_texture_default(int prefab);              // 2 for ladders, else 0

const cJSON *schema_limits(void);
double schema_limit(const char *name, double def);
const cJSON *schema_triggers(void);                  // {events, actions, conditions, emitter_sounds}
int schema_event_count(void);
int schema_action_count(void);
const char *schema_event_name(int id);
const char *schema_action_name(int id);
int schema_event_find(const char *name);             // name, v3 name or number; -1
int schema_action_find(const char *name);
const cJSON *schema_map_key(const char *key);        // map_keys entry or NULL

// Embedded data (schema_embed.c, generated by embed.cmake).
extern const unsigned char kn_schema_json[];
extern const size_t kn_schema_json_len;
